import CoverCanvas from "./cover-canvas";

/**
 * PersonaLane — one lane of a run: the keyframe a persona saw, its verbatim
 * final report, and a status chip. Failed lanes render as muted
 * "gave up" states and stay visible. The screenshot sits under a resolve-cover
 * veil that dissolves when the lane activates (reduced motion sees the
 * finished screenshot).
 *
 * The keyframe loads lazily: lanes live below the fold (in a replay track, or
 * stacked as a list on narrow screens), and eager keyframes otherwise get
 * hoisted into <head> as image preloads that compete with the first screen.
 */

export interface PersonaLaneProps {
  /** Two-digit lane index, e.g. "01" — also the cover-canvas glyph. */
  idx: string;
  /** Lane name as declared in the lab, e.g. "sticky-notes". */
  name: string;
  /** Keyframe screenshot for this lane. */
  img: string;
  alt: string;
  /** Caption label, e.g. "Final report — verbatim". */
  reportLabel: string;
  /** The persona's report, quoted verbatim. */
  report: string;
  passed: boolean;
  /** Right side of the panel bar. */
  right?: string;
  /** Chip text for each outcome. */
  passLabel?: string;
  failLabel?: string;
  /** Step index when composed inside a replay track. */
  dataI?: number;
  /** Marks the panel that sizes the stage in a replay track. */
  sizer?: boolean;
}

export default function PersonaLane({
  idx,
  name,
  img,
  alt,
  reportLabel,
  report,
  passed,
  right = "observer · replay",
  passLabel = "Passed",
  failLabel = "Gave up",
  dataI,
  sizer,
}: PersonaLaneProps) {
  return (
    <article
      className="panel"
      {...(dataI !== undefined ? { "data-i": dataI } : {})}
      {...(sizer ? { "data-sizer": "" } : {})}
    >
      <header className="pbar">
        <span className="pl">
          <b className="pidx">{idx}</b>
          <span className="pname">{name}</span>
        </span>
        <span className="pr">{right}</span>
      </header>
      <div className="pmedia">
        <img src={img} alt={alt} loading="lazy" />
        <CoverCanvas n={idx} />
      </div>
      <footer className="pcap">
        <p className="prep">
          <span className="plab">{reportLabel}</span>
          <q>{report}</q>
        </p>
        {passed ? (
          <span className="chip chip-pass">{passLabel}</span>
        ) : (
          <span className="chip chip-dot chip-mute">{failLabel}</span>
        )}
      </footer>
    </article>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { registerCover, resolveCover } from "@/lib/covers";
import { prefersReducedMotion } from "@/lib/theme";

/**
 * CoverCanvas — one resolve-cover veil over a screenshot. Registers itself
 * with the shared cover engine on mount; reduced motion removes it (finished
 * state = the plain screenshot), exactly like the POC.
 *
 * `resolveAfter` (ms) self-resolves after mount — used by the hero tile
 * (1100ms). Panels inside PinnedReplay omit it; the replay triggers them.
 */
export default function CoverCanvas({ n, resolveAfter }: { n: string; resolveAfter?: number }) {
  const ref = useRef<HTMLCanvasElement>(null);
  const [removed, setRemoved] = useState(false);

  useEffect(() => {
    const c = ref.current;
    if (!c) return;
    if (prefersReducedMotion()) {
      setRemoved(true);
      return;
    }
    const unregister = registerCover(c, n);
    if (resolveAfter !== undefined) resolveCover(c, resolveAfter);
    return unregister;
  }, [n, resolveAfter]);

  if (removed) return null;
  return <canvas className="cover" data-n={n} ref={ref}></canvas>;
}

"use client";

import { TH, onThemeRedraw } from "./theme";

/**
 * Resolve covers: a dash-texture veil drawn over each evidence screenshot
 * that "resolves" left-to-right into the real image, once, when its panel
 * becomes active. Ported from the POC's initCovers/resolveCover.
 *
 * Reduced motion never registers a cover (the POC removes them), so those
 * visitors see finished states: the plain screenshots.
 */

const CELL = 8;

interface CoverItem {
  c: HTMLCanvasElement;
  ctx: CanvasRenderingContext2D;
  n: string;
  p: number;
  done: boolean;
  built: boolean;
  anim: boolean;
  start: number;
  lum: Uint8ClampedArray | null;
  gw: number;
  gh: number;
  W: number;
  H: number;
}

const items: CoverItem[] = [];
const byCanvas = new WeakMap<HTMLCanvasElement, CoverItem>();
let raf = 0;
let wired = false;

function hash(x: number, y: number): number {
  const h = Math.sin(x * 127.1 + y * 311.7) * 43758.5453;
  return h - Math.floor(h);
}

function build(it: CoverItem): void {
  const parent = it.c.parentElement;
  if (!parent) return;
  const r = parent.getBoundingClientRect();
  it.W = Math.max(1, r.width | 0);
  it.H = Math.max(1, r.height | 0);
  const d = Math.min(2, window.devicePixelRatio || 1);
  it.c.width = it.W * d;
  it.c.height = it.H * d;
  it.ctx.setTransform(d, 0, 0, d, 0, 0);
  it.gw = Math.ceil(it.W / CELL);
  it.gh = Math.ceil(it.H / CELL);
  const o = document.createElement("canvas");
  o.width = it.gw;
  o.height = it.gh;
  const oc = o.getContext("2d", { willReadFrequently: true });
  if (!oc) return;
  oc.setTransform(1 / CELL, 0, 0, 1 / CELL, 0, 0);
  oc.fillStyle = "#101010";
  oc.fillRect(0, 0, it.W + CELL, it.H + CELL);
  const Wd = it.W;
  const Hd = it.H;
  oc.fillStyle = "rgba(255,255,255,0.86)";
  oc.beginPath();
  oc.arc(Wd * 0.33, Hd * 0.4, Hd * 0.145, 0, 7);
  oc.fill();
  oc.beginPath();
  oc.ellipse(Wd * 0.33, Hd * 0.86, Hd * 0.3, Hd * 0.26, 0, 0, 7);
  oc.fill();
  oc.fillStyle = "rgba(255,255,255,0.95)";
  // Canvas cannot resolve var(); read the concrete --mono stack (next/font
  // family names) so the digits render in Geist Mono like the POC.
  const mono =
    getComputedStyle(document.documentElement).getPropertyValue("--mono").trim() ||
    'ui-monospace,"SF Mono",Menlo,Consolas,monospace';
  oc.font = `500 ${Hd * 0.46}px ${mono}`;
  oc.textBaseline = "middle";
  oc.textAlign = "center";
  oc.fillText(it.n, Wd * 0.66, Hd * 0.52);
  it.lum = oc.getImageData(0, 0, it.gw, it.gh).data;
  it.built = true;
}

function drawItem(it: CoverItem): void {
  if (!it.built) build(it);
  if (!it.lum) return;
  const ctx = it.ctx;
  ctx.clearRect(0, 0, it.W, it.H);
  for (let y = 0; y < it.gh; y++) {
    const wob = Math.sin(y * 0.55) * 2.1;
    for (let x = 0; x < it.gw; x++) {
      const h = (x / it.gw) * 0.72 + hash(x, y) * 0.28;
      if (h < it.p) continue;
      ctx.fillStyle = TH.cover;
      ctx.fillRect(x * CELL - 0.5, y * CELL - 0.5, CELL + 1, CELL + 1);
      const L = (it.lum[(y * it.gw + x) * 4] ?? 0) / 255;
      if (L < 0.07) continue;
      const len = Math.min(CELL - 1.4, 1 + L * (CELL - 1.8));
      const frontier = h < it.p + 0.07 && it.p > 0;
      ctx.strokeStyle = frontier ? TH.accent : `rgba(${TH.ink},${0.18 + L * 0.55})`;
      ctx.lineWidth = 0.9 + L * 1.9;
      ctx.lineCap = "round";
      ctx.beginPath();
      ctx.moveTo(x * CELL + CELL / 2 - len / 2 + wob, y * CELL + CELL / 2);
      ctx.lineTo(x * CELL + CELL / 2 + len / 2 + wob, y * CELL + CELL / 2);
      ctx.stroke();
    }
  }
}

function tick(now: number): void {
  let any = false;
  items.forEach((it) => {
    if (!it.anim || it.done) return;
    const e = Math.min(1, (now - it.start) / 950);
    const k = e < 0.5 ? 4 * e * e * e : 1 - Math.pow(-2 * e + 2, 3) / 2;
    it.p = k * 1.14;
    if (e >= 1) {
      it.done = true;
      it.anim = false;
      it.c.remove();
      return;
    }
    drawItem(it);
    any = true;
  });
  raf = any ? requestAnimationFrame(tick) : 0;
}

function wire(): void {
  if (wired) return;
  wired = true;
  onThemeRedraw(() => {
    items.forEach((it) => {
      if (!it.done) drawItem(it);
    });
  });
  window.addEventListener("resize", () => {
    items.forEach((it) => {
      if (it.done) return;
      it.built = false;
      drawItem(it);
    });
  });
}

/** Register a cover canvas; draws the veil immediately. Returns an unregister fn. */
export function registerCover(c: HTMLCanvasElement, n: string): () => void {
  wire();
  const ctx = c.getContext("2d");
  if (!ctx) return () => {};
  const it: CoverItem = {
    c,
    ctx,
    n,
    p: 0,
    done: false,
    built: false,
    anim: false,
    start: 0,
    lum: null,
    gw: 0,
    gh: 0,
    W: 0,
    H: 0,
  };
  byCanvas.set(c, it);
  items.push(it);
  drawItem(it);
  return () => {
    const i = items.indexOf(it);
    if (i !== -1) items.splice(i, 1);
    byCanvas.delete(c);
  };
}

/** Resolve a cover into its screenshot after `delay` ms; runs once per cover. */
export function resolveCover(c: HTMLCanvasElement | null, delay?: number): void {
  const it = c ? byCanvas.get(c) : undefined;
  if (!it || it.done || it.anim) return;
  setTimeout(() => {
    if (it.done || it.anim) return;
    it.anim = true;
    it.start = performance.now();
    if (!raf) raf = requestAnimationFrame(tick);
  }, delay || 0);
}

"use client";

/**
 * Theme plumbing shared by every canvas island.
 *
 * Ported from the POC's theme block: canvases paint with the resolved values
 * of --crowd-ink / --accent-canvas / --cover-bg, so on any theme change they
 * re-read the tokens and repaint. The toggle writes data-theme on <html>
 * (persisted to localStorage by the toggle itself); the OS-level
 * prefers-color-scheme listener covers system flips while no explicit
 * choice is set.
 */

export const TH = { ink: "28,26,22", accent: "#2b3fd6", cover: "#ffffff" };

const redraws: Array<() => void> = [];
let wired = false;

export function themeVals(): void {
  const cs = getComputedStyle(document.documentElement);
  TH.ink = cs.getPropertyValue("--crowd-ink").trim() || TH.ink;
  TH.accent = cs.getPropertyValue("--accent-canvas").trim() || TH.accent;
  TH.cover = cs.getPropertyValue("--cover-bg").trim() || TH.cover;
}

export function curTheme(): "light" | "dark" {
  const a = document.documentElement.getAttribute("data-theme");
  if (a === "light" || a === "dark") return a;
  return window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
}

export function syncTheme(): void {
  themeVals();
  redraws.forEach((f) => f());
}

export function onThemeRedraw(fn: () => void): () => void {
  wire();
  redraws.push(fn);
  return () => {
    const i = redraws.indexOf(fn);
    if (i !== -1) redraws.splice(i, 1);
  };
}

function wire(): void {
  if (wired) return;
  wired = true;
  themeVals();
  const mqDark = window.matchMedia("(prefers-color-scheme: dark)");
  if (mqDark.addEventListener) mqDark.addEventListener("change", syncTheme);
}

export function prefersReducedMotion(): boolean {
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

/* @humanish/persona-lane — generated from app/globals.css by scripts/extract-registry-css.mjs.
   Do not edit by hand; edit globals.css and run `pnpm registry:build`.
   Assumes a reset that zeroes margins/padding and sets border-box
   (e.g. Tailwind Preflight); the spacing these components depend on is also
   pinned explicitly below. Colors come from the humanish token system
   (@humanish/humanish-tokens); fonts fall back to system stacks unless
   --font-newsreader / --font-geist / --font-geist-mono are provided. */

.pmedia canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: var(--space-6);
  font-family: var(--mono);
  font-size: var(--text-11);
  font-weight: 500;
  letter-spacing: 0.14em;
  color: var(--accent-ink);
  border: 1px solid var(--accent-dim);
  padding: var(--space-4) var(--space-8);
  border-radius: var(--radius-pill);
  white-space: nowrap;
}

.chip-pass::before {
  content: "✓";
  font-size: var(--text-11);
}

.chip-dot::before {
  content: "";
  width: 5px;
  height: 5px;
  border-radius: var(--radius-round);
  background: var(--accent-ink);
}

.chip-mute {
  color: var(--muted);
  border-color: var(--line);
}

.chip-mute::before {
  background: var(--muted);
}

.panel {
  display: flex;
  flex-direction: column;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius-14);
  overflow: hidden;
  box-shadow: var(--sh-panel);
}

.pbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--space-12);
  min-height: 40px;
  padding: var(--space-8) var(--space-16);
  border-bottom: 1px solid var(--line-soft);
  background: var(--accent-wash);
}

.pl {
  display: flex;
  align-items: baseline;
  gap: var(--space-12);
  min-width: 0;
}

.pidx {
  font-family: var(--mono);
  font-size: var(--text-11);
  font-weight: 500;
  color: var(--accent-ink);
  letter-spacing: 0.08em;
}

.pname {
  font-family: var(--mono);
  font-size: var(--text-11);
  color: var(--ink);
  letter-spacing: 0.09em;
  text-transform: uppercase;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.pr {
  font-family: var(--mono);
  font-size: var(--text-11);
  color: var(--label);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  white-space: nowrap;
}

.pmedia {
  position: relative;
  flex: 0 0 auto;
  background: var(--mineral);
}

.pmedia img {
  display: block;
  width: 100%;
  aspect-ratio: 598/324;
  object-fit: cover;
}

.pcap {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--space-14);
  min-height: 52px;
  padding: var(--space-12) var(--space-16);
  border-top: 1px solid var(--line-soft);
}

.prep {
  margin: 0;
  min-width: 0;
  font-size: var(--text-13);
  color: var(--body-c);
}

.plab {
  display: block;
  font-family: var(--mono);
  font-size: var(--text-11);
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--label);
  margin-bottom: var(--space-4);
}

.prep q {
  font-family: var(--mono);
  font-size: var(--text-12);
  color: var(--ink);
  quotes: "\201C" "\201D";
}

.prep code {
  font-size: 0.92em;
}

@media (max-width: 420px) {
  .pbar {
      flex-wrap: wrap;
      row-gap: var(--space-2);
      padding-top: var(--space-10);
      padding-bottom: var(--space-10);
  }
  .pname {
      white-space: normal;
      overflow: visible;
      text-overflow: clip;
  }
  .pr {
      white-space: normal;
  }
}

@media (max-width: 1023px) {
  .panel {
      box-shadow: var(--sh-rail);
  }
}
